{
  "correction_rules": [
    "When sentiment is positive (≥ 0.25), reduce forecasted price by 5-10% to account for overconfidence bias.",
    "When sentiment is negative (≤ -0.25), increase forecasted price by 5-10% to counteract pessimism-induced undershooting.",
    "After a sharp price spike (≥ 10% from prior peak), apply a 10-15 day lag correction: reduce forecast by 5-8% for the next 3-5 days to avoid overshoot.",
    "If true outcome consistently deviates below forecast (persistent underperformance), apply mean reversion: adjust forecast toward recent 5-day average, especially if sentiment is neutral.",
    "For long-term forecasts (30-day horizon), if true outcome shows downward trend after 10+ days, reduce forecast slope by 10-15% to reflect market exhaustion.",
    "If sentiment history shows increasing negativity over 3 consecutive days, apply a 5-10% downward bias correction to prevent overcorrection."
  ]
}
